import { Item as RadixItem } from '@radix-ui/react-dropdown-menu';
import React, { forwardRef, ReactEventHandler, useState } from 'react';

import { getItemSlots } from './item-slots.js';
import { StyledMenuItem, StyledMenuItemChildren } from './ItemStyles.js';
import { MenuItemTooltipWrapper } from './ItemTooltip.js';
import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { _useTooltipState } from '../../overlays/hooks/useTooltipState.js';

export interface MenuItemOwnProps
  extends WithChildren,
    AriaLabelingProps,
    StylingProps,
    DataTestId {
  /**
   * Whether the menu item is disabled.
   * If `true`, it prevents the user from interacting with the item and the item
   * being focused.
   */
  disabled?: boolean;
  /**
   * Optional text used for typeahead purposes. By default, the typeahead
   * behavior will use the `.textContent` of the item. Use this when the content
   * is complex, or you have non-textual content inside.
   */
  textValue?: string;
  /**
   * Event handler called when the user selects an item (via mouse or keyboard).
   * Calling `event.preventDefault()` in this handler prevents the dropdown menu
   * from closing when selecting that item.
   */
  onSelect: ReactEventHandler;
}

export type MenuItemProps<E extends React.ElementType> =
  PolymorphicComponentProps<E, MenuItemOwnProps>;

/**
 * The component that contains the dropdown menu Items.
 */
export const Item: <E extends React.ElementType = 'div'>(
  props: MenuItemProps<E>,
) => React.ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends React.ElementType>(
    {
      children,
      disabled = false,
      onSelect,
      as,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      'aria-describedby': ariaDescribedBy,
      'aria-details': ariaDetails,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: MenuItemProps<E>,
    forwardedRef: typeof remainingProps.ref,
  ) => {
    const slots = getItemSlots(children);
    const {
      isOpen,
      open: openTooltip,
      close: closeTooltip,
    } = _useTooltipState({
      defaultOpen: false,
    });
    const [tooltipTriggerRef, setTooltipTriggerRef] =
      useState<HTMLElement | null>(null);
    const { focusProps, focusStyles, isFocusVisible } = useFocusRing();

    return (
      <>
        <RadixItem
          data-testid={dataTestId}
          ref={forwardedRef}
          {..._mergeProps(focusProps, {
            // We have no choice but to enforce casting here as the native DOM Event
            // is not fully compatible with the ReactEventHandler
            onSelect: (event) => {
              if (disabled) {
                event.stopPropagation();
                event.preventDefault();
                return;
              }
              onSelect(event);
            },
            onFocus: () => slots.tooltip && !disabled && openTooltip(true),
            onBlur: () => slots.tooltip && !disabled && closeTooltip(true),
            className: consumerClassName,
            style: consumerStyle,
          })}
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          aria-describedby={ariaDescribedBy}
          aria-details={ariaDetails}
          asChild
        >
          <StyledMenuItem
            {...remainingProps}
            disabled={disabled}
            $isFocusVisible={isFocusVisible}
            $focusStyle={focusStyles}
            // TODO LeMa: role actually belongs on top-level element (check for side effects regarding tests after moving the attribute!)
            role="menuitem"
            aria-disabled={disabled}
            ref={setTooltipTriggerRef}
            as={as !== undefined ? as : 'div'}
          >
            {slots.icon}
            <StyledMenuItemChildren className="item-children">
              {slots.freeform}
            </StyledMenuItemChildren>
          </StyledMenuItem>
        </RadixItem>
        {isOpen === true && (
          <MenuItemTooltipWrapper triggerElement={tooltipTriggerRef}>
            {slots.tooltip}
          </MenuItemTooltipWrapper>
        )}
      </>
    );
  },
);

(Item as typeof Item & { displayName: string }).displayName = 'Menu.Item';
